(305268,33919,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Todo un profesional: el tic está en verde, así que el socio ...'::text,'va a pasar'::text,'pasará'::text,NULL::text,'Todo un profesional: el tic está en verde, así que el socio va a pasar.'::text),
(305267,33919,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un vrai pro : la coche est verte, donc le membre ...'::text,'va passer'::text,'passera'::text,NULL::text,'Un vrai pro : la coche est verte, donc le membre va passer.'::text),
(305270,33919,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tam bir profesyonel: tik yeşil, bu yüzden üye içeri ...'::text,'geçecek'::text,'geçecek'::text,NULL::text,'Tam bir profesyonel: tik yeşil, bu yüzden üye içeri geçecek.'::text),
(305271,33919,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Igazi profi: a pipa zöld, szóval a tag ...'::text,'át fog menni'::text,'át fog menni'::text,NULL::text,'Igazi profi: a pipa zöld, szóval a tag át fog menni.'::text),
(328422,36492,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr neues Sommerkleid ... knallgelb.'::text,'ist'::text,'sind'::text,'bin'::text,'Ihr neues Sommerkleid ist knallgelb.'::text),
(328426,36492,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її нова літня сукня ... яскраво-жовта.'::text,'є'::text,'є'::text,'є'::text,'Її нова літня сукня є яскраво-жовта.'::text),
(328425,36492,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su nuevo vestido de verano ... amarillo chillón.'::text,'es'::text,'son'::text,'soy'::text,'Su nuevo vestido de verano es amarillo chillón.'::text),
(328424,36492,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa nouvelle robe d''été ... jaune vif.'::text,'est'::text,'sont'::text,'suis'::text,'Sa nouvelle robe d''été est jaune vif.'::text),
(328427,36492,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun yeni yazlık elbisesi parlak sarı ...'::text,''::text,NULL::text,NULL::text,'Onun yeni yazlık elbisesi parlak sarı.'::text),
(328428,36492,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az új nyári ruhája ... élénksárga.'::text,''::text,NULL::text,'vagyok'::text,'Az új nyári ruhája élénksárga.'::text),
(328485,36499,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein sehr ruhiger Moment, klar: Sie dreht sich ... in ihrem gelben Kleid.'::text,'wild'::text,'wild'::text,'wilder'::text,'Ein sehr ruhiger Moment, klar: Sie dreht sich wild in ihrem gelben Kleid.'::text),
(328489,36499,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дуже спокійний момент, очевидно: вона ... крутиться у своїй жовтій сукні.'::text,'шалено'::text,'шалений'::text,'шаленіший'::text,'Дуже спокійний момент, очевидно: вона шалено крутиться у своїй жовтій сукні.'::text),
(328488,36499,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un momento muy tranquilo, obviamente: ella gira ... con su vestido amarillo.'::text,'locamente'::text,'loco'::text,'más loco'::text,'Un momento muy tranquilo, obviamente: ella gira locamente con su vestido amarillo.'::text),
(328487,36499,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un moment très calme, évidemment : elle tourne ... dans sa robe jaune.'::text,'follement'::text,'fou'::text,'plus fou'::text,'Un moment très calme, évidemment : elle tourne follement dans sa robe jaune.'::text),
(328490,36499,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok sakin bir an tabii: o sarı elbisesiyle ... dönüyor.'::text,'çılgınca'::text,'çılgın'::text,'daha çılgın'::text,'Çok sakin bir an tabii: o sarı elbisesiyle çılgınca dönüyor.'::text),
(328491,36499,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon nyugodt pillanat, persze: ő ... pörög a sárga ruhájában.'::text,'vadul'::text,'vad'::text,'vadabb'::text,'Nagyon nyugodt pillanat, persze: ő vadul pörög a sárga ruhájában.'::text),
(311133,34571,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr neues Kleid im Esszimmer ... lila.'::text,'ist'::text,'sind'::text,'sein'::text,'Ihr neues Kleid im Esszimmer ist lila.'::text),
(311137,34571,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її нова сукня в їдальні ... фіолетова.'::text,'є'::text,'є'::text,'бути'::text,'Її нова сукня в їдальні є фіолетова.'::text),
(311136,34571,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su vestido nuevo en el comedor ... morado.'::text,'es'::text,'son'::text,'ser'::text,'Su vestido nuevo en el comedor es morado.'::text),
(311135,34571,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa nouvelle robe dans la salle à manger ... violette.'::text,'est'::text,'sont'::text,'être'::text,'Sa nouvelle robe dans la salle à manger est violette.'::text),
(311138,34571,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yemek odasındaki yeni elbisesi mor ...'::text,''::text,NULL::text,'olmak'::text,'Yemek odasındaki yeni elbisesi mor.'::text),
(311139,34571,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az új ruhája az ebédlőben ... lila.'::text,''::text,NULL::text,'lenni'::text,'Az új ruhája az ebédlőben lila.'::text),
(311169,34575,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dresscode: Lila! Sie ... dieses Kleid tragen, sonst ist es eine Katastrophe!'::text,'muss'::text,'muss'::text,'sollte'::text,'Dresscode: Lila! Sie muss dieses Kleid tragen, sonst ist es eine Katastrophe!'::text),
(311173,34575,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дрес-код: фіолетовий! Вона ... вдягнути цю сукню, інакше катастрофа!'::text,'має'::text,'мусить'::text,'мала б'::text,'Дрес-код: фіолетовий! Вона має вдягнути цю сукню, інакше катастрофа!'::text),
(311172,34575,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Código de vestimenta: morado! ¡Ella ... llevar este vestido o es un desastre!'::text,'tiene que'::text,'debe'::text,'debería'::text,'¡Código de vestimenta: morado! ¡Ella tiene que llevar este vestido o es un desastre!'::text),
(311171,34575,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dress code : violet ! Elle ... porter cette robe, sinon c''est la catastrophe !'::text,'doit'::text,'doit'::text,'devrait'::text,'Dress code : violet ! Elle doit porter cette robe, sinon c''est la catastrophe !'::text),
(311174,34575,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kıyafet kuralı: mor! O bu elbiseyi ..., yoksa felaket!'::text,'giymek zorunda'::text,'giymeli'::text,'giymeli'::text,'Kıyafet kuralı: mor! O bu elbiseyi giymek zorunda, yoksa felaket!'::text),
(311175,34575,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dresszkód: lila! Neki ... ezt a ruhát viselnie, különben katasztrófa!'::text,'kell'::text,'kell'::text,'kellene'::text,'Dresszkód: lila! Neki kell ezt a ruhát viselnie, különben katasztrófa!'::text),
(298398,33156,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Frisur mit zwei Dutts ist neu.'::text,'Diese'::text,'Diese'::text,'Jene'::text,'Diese Frisur mit zwei Dutts ist neu.'::text),
(298402,33156,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... зачіска з двома гульками нова.'::text,'Ця'::text,'Ці'::text,'Ті'::text,'Ця зачіска з двома гульками нова.'::text),
(298401,33156,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... peinado con dos moños es nuevo.'::text,'Este'::text,'Estos'::text,'Esos'::text,'Este peinado con dos moños es nuevo.'::text),
(298400,33156,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... coiffure à deux chignons est nouvelle.'::text,'Cette'::text,'Ces'::text,'Ces'::text,'Cette coiffure à deux chignons est nouvelle.'::text),
(298403,33156,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... iki topuzlu saç modeli yeni.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu iki topuzlu saç modeli yeni.'::text),
(298404,33156,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a két kontyos frizura új.'::text,'Ez'::text,'Ezek'::text,'Azok'::text,'Ez a két kontyos frizura új.'::text),
(298425,33159,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie braucht ... Zeit für ihre neue Frisur.'::text,'etwas'::text,'viele'::text,'ein paar'::text,'Sie braucht etwas Zeit für ihre neue Frisur.'::text),
(298429,33159,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона потребує ... часу для своєї нової зачіски.'::text,'трохи'::text,'багато'::text,'кілька'::text,'Вона потребує трохи часу для своєї нової зачіски.'::text),
(298428,33159,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella necesita ... tiempo para su nuevo peinado.'::text,'algo de'::text,'muchos'::text,'unos pocos'::text,'Ella necesita algo de tiempo para su nuevo peinado.'::text),
(298427,33159,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il lui faut ... temps pour sa nouvelle coiffure.'::text,'du'::text,'beaucoup de'::text,'quelques'::text,'Il lui faut du temps pour sa nouvelle coiffure.'::text),
(298430,33159,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, yeni saç modeli için ... zamana ihtiyaç duyuyor.'::text,'biraz'::text,'çok'::text,'birkaç'::text,'O, yeni saç modeli için biraz zamana ihtiyaç duyuyor.'::text),
(298431,33159,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neki ... időre van szüksége az új frizurájához.'::text,'némi'::text,'sok'::text,'pár'::text,'Neki némi időre van szüksége az új frizurájához.'::text),
(297471,33053,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Farbe hat das Kleid des Models? Es ist grün.'::text,'Welche'::text,'Wer'::text,'Wo'::text,'Welche Farbe hat das Kleid des Models? Es ist grün.'::text),
(297475,33053,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... кольору сукня моделі? Вона зелена.'::text,'Якого'::text,'Хто'::text,'Де'::text,'Якого кольору сукня моделі? Вона зелена.'::text),
(297474,33053,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿De ... color es el vestido de la modelo? Es verde.'::text,'qué'::text,'quién'::text,'dónde'::text,'¿De qué color es el vestido de la modelo? Es verde.'::text),
(297473,33053,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De ... couleur est la robe du mannequin ? Elle est verte.'::text,'quelle'::text,'qui'::text,'où'::text,'De quelle couleur est la robe du mannequin ? Elle est verte.'::text),
(297476,33053,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Modelin elbisesi ... renkte? O yeşil.'::text,'ne'::text,'kim'::text,'nerede'::text,'Modelin elbisesi ne renkte? O yeşil.'::text),
(297477,33053,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... színű a modell estélyije? Zöld.'::text,'Milyen'::text,'Ki'::text,'Hol'::text,'Milyen színű a modell estélyije? Zöld.'::text),
(297507,33057,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Models tragen hier sonst Schwarz, aber heute ... sie ein grünes Kleid.'::text,'trägt'::text,'trägt'::text,NULL::text,'Models tragen hier sonst Schwarz, aber heute trägt sie ein grünes Kleid.'::text),
(297511,33057,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Моделі тут зазвичай носять чорне, але сьогодні вона ... зелену сукню.'::text,'носить'::text,'носить'::text,NULL::text,'Моделі тут зазвичай носять чорне, але сьогодні вона носить зелену сукню.'::text),
(297510,33057,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aquí las modelos suelen llevar negro, pero hoy ella ... un vestido verde.'::text,'está llevando'::text,'lleva'::text,NULL::text,'Aquí las modelos suelen llevar negro, pero hoy ella está llevando un vestido verde.'::text),
(297509,33057,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ici, les mannequins portent d''habitude du noir, mais aujourd''hui elle ... une robe verte.'::text,'porte'::text,'porte'::text,NULL::text,'Ici, les mannequins portent d''habitude du noir, mais aujourd''hui elle porte une robe verte.'::text),
(297512,33057,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mankenler burada genelde siyah giyer ama bugün o yeşil bir elbise ...'::text,'giyiyor'::text,'giyer'::text,NULL::text,'Mankenler burada genelde siyah giyer ama bugün o yeşil bir elbise giyiyor.'::text),
(297513,33057,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A modellek itt általában feketét hordanak, de ma ő egy zöld estélyit ...'::text,'visel'::text,'visel'::text,NULL::text,'A modellek itt általában feketét hordanak, de ma ő egy zöld estélyit visel.'::text),
(319341,35483,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Diese Bronzestatue ... einen riesigen Bart!'::text,'hat'::text,'haben'::text,'hat'::text,'Albtraum! Diese Bronzestatue hat einen riesigen Bart!'::text),
(319345,35483,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Ця бронзова статуя ... величезну бороду!'::text,'має'::text,'мати'::text,'має'::text,'Жах! Ця бронзова статуя має величезну бороду!'::text),
(319344,35483,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¡Esta estatua de bronce ... una barba enorme!'::text,'tiene'::text,'tienen'::text,'tiene'::text,'¡Pesadilla! ¡Esta estatua de bronce tiene una barba enorme!'::text),
(319343,35483,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! Cette statue en bronze ... une barbe énorme !'::text,'a'::text,'ont'::text,'a'::text,'Cauchemar ! Cette statue en bronze a une barbe énorme !'::text),
(319346,35483,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Bu bronz heykelin kocaman bir sakalı ...!'::text,'var'::text,'var'::text,'var'::text,'Kâbus! Bu bronz heykelin kocaman bir sakalı var!'::text),
(319347,35483,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! Ennek a bronzszobornak hatalmas szakálla ...!'::text,'van'::text,'van'::text,'van'::text,'Rémálom! Ennek a bronzszobornak hatalmas szakálla van!'::text),
(319386,35488,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Parkregel, offensichtlich eine lustige: Besucher ... sich von der Statue fernhalten.'::text,'müssen'::text,'müssen'::text,'sollten'::text,'Parkregel, offensichtlich eine lustige: Besucher müssen sich von der Statue fernhalten.'::text),
(319390,35488,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Правило парку, явно дуже веселе: відвідувачі ... триматися подалі від статуї.'::text,'мають'::text,'мусять'::text,'мали б'::text,'Правило парку, явно дуже веселе: відвідувачі мають триматися подалі від статуї.'::text),
(319389,35488,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Norma del parque, claramente muy divertida: los visitantes ... mantenerse lejos de la estatua.'::text,'tienen que'::text,'deben'::text,'deberían'::text,'Norma del parque, claramente muy divertida: los visitantes tienen que mantenerse lejos de la estatua.'::text),
(319388,35488,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Règle du parc, clairement très fun : les visiteurs ... rester loin de la statue.'::text,'doivent'::text,'doivent'::text,'devraient'::text,'Règle du parc, clairement très fun : les visiteurs doivent rester loin de la statue.'::text),
(319391,35488,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Park kuralı, belli ki çok eğlenceli: ziyaretçiler heykelden uzak ...'::text,'durmak zorunda'::text,'durmalı'::text,'durmalı'::text,'Park kuralı, belli ki çok eğlenceli: ziyaretçiler heykelden uzak durmak zorunda.'::text),
(319392,35488,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Parkszabály, nyilván nagyon vicces: a látogatóknak ... távol maradniuk a szobortól.'::text,'kell'::text,'kell'::text,'kellene'::text,'Parkszabály, nyilván nagyon vicces: a látogatóknak kell távol maradniuk a szobortól.'::text),
(305715,33969,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Mutter hat ... hungrige Kinder und einen Pfannkuchen! Katastrophe!'::text,'drei'::text,'dritte'::text,'Dreien'::text,'Die Mutter hat drei hungrige Kinder und einen Pfannkuchen! Katastrophe!'::text),
(305719,33969,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мама має ... голодних дітей і один млинець! Катастрофа!'::text,'трьох'::text,'третіх'::text,'трійки'::text,'Мама має трьох голодних дітей і один млинець! Катастрофа!'::text),
(305718,33969,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La madre tiene ... hijos hambrientos y una tortita! ¡Desastre!'::text,'tres'::text,'terceros'::text,'tres'::text,'¡La madre tiene tres hijos hambrientos y una tortita! ¡Desastre!'::text),
(305717,33969,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mère a ... enfants affamés et une crêpe ! Catastrophe !'::text,'trois'::text,'troisièmes'::text,'trois'::text,'La mère a trois enfants affamés et une crêpe ! Catastrophe !'::text),
(305720,33969,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Annenin ... aç çocuğu ve bir pankeki var! Felaket!'::text,'üç'::text,'üçüncü'::text,'üçler'::text,'Annenin üç aç çocuğu ve bir pankeki var! Felaket!'::text),
(305721,33969,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az anyának ... éhes gyereke és egy palacsintája van! Katasztrófa!'::text,'három'::text,'harmadik'::text,'hármasok'::text,'Az anyának három éhes gyereke és egy palacsintája van! Katasztrófa!'::text),
(305733,33971,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, pass auf: Die Mutter ... morgen Pfannkuchen für die ganze Klasse machen, hat sie gesagt.'::text,'wird'::text,'machen'::text,'wird'::text,'Okay, pass auf: Die Mutter wird morgen Pfannkuchen für die ganze Klasse machen, hat sie gesagt.'::text),
(305737,33971,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, мама завтра ... млинці для всього класу, так вона сказала.'::text,'збирається напекти'::text,'пекти'::text,'збирається напекти'::text,'Коротше, мама завтра збирається напекти млинці для всього класу, так вона сказала.'::text),
(305736,33971,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues la madre ... tortitas para toda la clase mañana, eso dijo.'::text,'va a hacer'::text,'hacer'::text,'va a hacer'::text,'Vale, pues la madre va a hacer tortitas para toda la clase mañana, eso dijo.'::text),
(305735,33971,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, alors la mère ... des crêpes pour toute la classe demain, elle l''a dit.'::text,'va faire'::text,'faire'::text,'va faire'::text,'Bon, alors la mère va faire des crêpes pour toute la classe demain, elle l''a dit.'::text),
(305738,33971,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, anne yarın bütün sınıf için pankek ..., öyle dedi.'::text,'yapacak'::text,'yapmak'::text,'yapacak'::text,'Tamam, anne yarın bütün sınıf için pankek yapacak, öyle dedi.'::text),
(305739,33971,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval az anya holnap palacsintát ... az egész osztálynak, ő mondta.'::text,'fog sütni'::text,'sütni'::text,'fog sütni'::text,'Oké, szóval az anya holnap palacsintát fog sütni az egész osztálynak, ő mondta.'::text),
(305823,33981,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er verkauft das grüne und kauft ... riesiges schwarzes Motorrad! Ende!'::text,'ein'::text,'ein'::text,'das'::text,'Er verkauft das grüne und kauft ein riesiges schwarzes Motorrad! Ende!'::text),
(305827,33981,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він продає зелений і купує ... величезний чорний мотоцикл! Кінець!'::text,''::text,NULL::text,NULL::text,'Він продає зелений і купує величезний чорний мотоцикл! Кінець!'::text),
(305826,33981,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Él vende la verde y compra ... moto negra enorme! ¡Fin!'::text,'una'::text,'una'::text,'la'::text,'¡Él vende la verde y compra una moto negra enorme! ¡Fin!'::text),
(305825,33981,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il vend la verte et achète ... énorme moto noire ! Fin !'::text,'une'::text,'une'::text,'l'''::text,'Il vend la verte et achète une énorme moto noire ! Fin !'::text),
(305828,33981,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O yeşil olanı satıyor ve ... kocaman siyah motosiklet alıyor! Son!'::text,'bir'::text,'bir'::text,NULL::text,'O yeşil olanı satıyor ve bir kocaman siyah motosiklet alıyor! Son!'::text),
(305829,33981,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő eladja a zöldet, és vesz ... hatalmas fekete motort! Vége!'::text,'egy'::text,'egy'::text,'a'::text,'Ő eladja a zöldet, és vesz egy hatalmas fekete motort! Vége!'::text),
(305850,33984,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sein grünes Motorrad lief gut, ... natürlich brauchte er ein größeres.'::text,'aber'::text,'also'::text,'weil'::text,'Sein grünes Motorrad lief gut, aber natürlich brauchte er ein größeres.'::text),
(305854,33984,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його зелений мотоцикл чудово працював, ... звісно ж, йому був потрібен більший.'::text,'але'::text,'тому'::text,'бо'::text,'Його зелений мотоцикл чудово працював, але звісно ж, йому був потрібен більший.'::text),
(305853,33984,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su moto verde funcionaba bien, ... obviamente él necesitaba una más grande.'::text,'pero'::text,'así que'::text,'porque'::text,'Su moto verde funcionaba bien, pero obviamente él necesitaba una más grande.'::text),
(305852,33984,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa moto verte marchait bien, ... évidemment il lui en fallait une plus grande.'::text,'mais'::text,'donc'::text,'parce que'::text,'Sa moto verte marchait bien, mais évidemment il lui en fallait une plus grande.'::text),
(305855,33984,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yeşil motosikleti gayet iyi çalışıyordu, ... tabii ki daha büyüğüne ihtiyacı vardı.'::text,'ama'::text,'bu yüzden'::text,'çünkü'::text,'Yeşil motosikleti gayet iyi çalışıyordu, ama tabii ki daha büyüğüne ihtiyacı vardı.'::text),
(305856,33984,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A zöld motorja jól működött, ... nyilván egy nagyobb kellett neki.'::text,'de'::text,'ezért'::text,'mert'::text,'A zöld motorja jól működött, de nyilván egy nagyobb kellett neki.'::text),
(299559,33285,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Helfer kosten null Euro. Super fürs Budget.'::text,'Diese'::text,'Dieser'::text,'Jener'::text,'Diese Helfer kosten null Euro. Super fürs Budget.'::text),
(299563,33285,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... помічники коштують нуль євро. Супер для бюджету.'::text,'Ці'::text,'Цей'::text,'Той'::text,'Ці помічники коштують нуль євро. Супер для бюджету.'::text),
(299562,33285,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ayudantes cuestan cero euros. Genial para el presupuesto.'::text,'Estos'::text,'Este'::text,'Ese'::text,'Estos ayudantes cuestan cero euros. Genial para el presupuesto.'::text),
(299561,33285,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... aides coûtent zéro euro. Top pour le budget.'::text,'Ces'::text,'Cet'::text,'Cet'::text,'Ces aides coûtent zéro euro. Top pour le budget.'::text),
(299564,33285,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... yardımcılar sıfır euroya mal oluyor. Bütçe için harika.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu yardımcılar sıfır euroya mal oluyor. Bütçe için harika.'::text),
(299565,33285,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a segítők nulla euróba kerülnek. Szuper a költségvetésnek.'::text,'Ezek'::text,'Ez'::text,'Az'::text,'Ezek a segítők nulla euróba kerülnek. Szuper a költségvetésnek.'::text),
(299613,33291,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, sie zieht sonst allein um, aber gestern ... ihr zwei Helfer, echt jetzt.'::text,'halfen'::text,'helfen'::text,NULL::text,'Digga, sie zieht sonst allein um, aber gestern halfen ihr zwei Helfer, echt jetzt.'::text),
(299617,33291,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона зазвичай переїжджає сама, але вчора їй ... двоє помічників, реально.'::text,'допомогли'::text,'допомагають'::text,NULL::text,'Бро, вона зазвичай переїжджає сама, але вчора їй допомогли двоє помічників, реально.'::text),
(299616,33291,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ella normalmente se muda sola, pero ayer dos ayudantes la ..., en serio.'::text,'ayudaron'::text,'ayudan'::text,NULL::text,'Bro, ella normalmente se muda sola, pero ayer dos ayudantes la ayudaron, en serio.'::text),
(299615,33291,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, d''habitude elle déménage seule, mais hier deux aides ..., sérieux.'::text,'l''ont aidée'::text,'l''aident'::text,NULL::text,'Frère, d''habitude elle déménage seule, mais hier deux aides l''ont aidée, sérieux.'::text),
(299618,33291,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o genelde yalnız taşınır ama dün ona iki yardımcı ..., cidden.'::text,'yardım etti'::text,'yardım eder'::text,NULL::text,'Kanka, o genelde yalnız taşınır ama dün ona iki yardımcı yardım etti, cidden.'::text),
(299619,33291,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő általában egyedül költözik, de tegnap két segítő ... neki, komolyan.'::text,'segített'::text,'segít'::text,NULL::text,'Tesó, ő általában egyedül költözik, de tegnap két segítő segített neki, komolyan.'::text),
(297705,33079,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein großer Pilz ... aus dem Boden.'::text,'wächst'::text,'wachsen'::text,'wachsend'::text,'Ein großer Pilz wächst aus dem Boden.'::text),
