(297707,33079,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un gros champignon ... du sol.'::text,'pousse'::text,'pousser'::text,'poussant'::text,'Un gros champignon pousse du sol.'::text),
(297710,33079,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyük bir mantar topraktan ...'::text,'biter'::text,'bitmek'::text,'biterek'::text,'Büyük bir mantar topraktan biter.'::text),
(297711,33079,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy nagy gomba ... ki a földből.'::text,'nő'::text,'nőni'::text,'növő'::text,'Egy nagy gomba nő ki a földből.'::text),
(306336,34038,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Straße hat eine Regel: Die Musik ... um neun aufhören.'::text,'muss'::text,'muss'::text,'sollte'::text,'Die Straße hat eine Regel: Die Musik muss um neun aufhören.'::text),
(306340,34038,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вулиця має правило: музика ... стихнути о дев''ятій.'::text,'має'::text,'мусить'::text,'мала б'::text,'Вулиця має правило: музика має стихнути о дев''ятій.'::text),
(306339,34038,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La calle tiene una norma: la música ... parar a las nueve.'::text,'tiene que'::text,'debe'::text,'debería'::text,'La calle tiene una norma: la música tiene que parar a las nueve.'::text),
(306338,34038,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La rue a une règle : la musique ... s''arrêter à neuf heures.'::text,'doit'::text,'doit'::text,'devrait'::text,'La rue a une règle : la musique doit s''arrêter à neuf heures.'::text),
(306341,34038,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sokağın bir kuralı var: müzik dokuzda ...'::text,'durmak zorunda'::text,'durmalı'::text,'durmalı'::text,'Sokağın bir kuralı var: müzik dokuzda durmak zorunda.'::text),
(306342,34038,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az utcának van egy szabálya: a zenének kilenckor ... abbamaradnia.'::text,'kell'::text,'kell'::text,'kellene'::text,'Az utcának van egy szabálya: a zenének kilenckor kell abbamaradnia.'::text),
(306435,34049,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das ... die Nationalfarben! Ich weine buchstäblich!'::text,'sind'::text,'ist'::text,'sein'::text,'Das sind die Nationalfarben! Ich weine buchstäblich!'::text),
(306439,34049,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Це ... національні кольори! Я буквально плачу!'::text,'є'::text,'є'::text,'бути'::text,'Це є національні кольори! Я буквально плачу!'::text),
(306438,34049,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Estos ... los colores nacionales! ¡Estoy llorando literalmente!'::text,'son'::text,'es'::text,'ser'::text,'¡Estos son los colores nacionales! ¡Estoy llorando literalmente!'::text),
(306437,34049,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce ... les couleurs nationales ! Je pleure littéralement !'::text,'sont'::text,'est'::text,'être'::text,'Ce sont les couleurs nationales ! Je pleure littéralement !'::text),
(306440,34049,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bunlar ulusal renkler ...! Resmen ağlıyorum!'::text,''::text,NULL::text,'olmak'::text,'Bunlar ulusal renkler! Resmen ağlıyorum!'::text),
