(306471,34053,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du bist heute ... als die ganze Nationalmannschaft.'::text,'lauter'::text,'lauter'::text,'am lautesten'::text,'Ehrlich, du bist heute lauter als die ganze Nationalmannschaft.'::text),
(306475,34053,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти сьогодні ... за всю національну збірну.'::text,'гучніший'::text,'більш гучний'::text,'найгучніший'::text,'Чесно, ти сьогодні гучніший за всю національну збірну.'::text),
(306474,34053,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, tú hoy eres ... que toda la selección nacional.'::text,'más ruidoso'::text,'más ruidoso'::text,'el más ruidoso'::text,'Sinceramente, tú hoy eres más ruidoso que toda la selección nacional.'::text),
(306473,34053,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu es ... que toute l''équipe nationale aujourd''hui.'::text,'plus bruyant'::text,'plus bruyant'::text,'le plus bruyant'::text,'Franchement, tu es plus bruyant que toute l''équipe nationale aujourd''hui.'::text),
(306476,34053,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası sen bugün bütün milli takımdan ...'::text,'daha gürültülüsün'::text,'daha gürültülüsün'::text,'en gürültülüsün'::text,'Açıkçası sen bugün bütün milli takımdan daha gürültülüsün.'::text),
