(309189,34355,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Karte ist voller kleiner ... und Fahnen.'::text,'Fotos'::text,'Foto'::text,'Fotos'::text,'Die Karte ist voller kleiner Fotos und Fahnen.'::text),
(309193,34355,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мапа повна маленьких ... і прапорців.'::text,'фотографій'::text,'фотографія'::text,'фотографій'::text,'Мапа повна маленьких фотографій і прапорців.'::text),
(309192,34355,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El mapa está lleno de pequeñas ... y banderas.'::text,'fotos'::text,'foto'::text,'fotos'::text,'El mapa está lleno de pequeñas fotos y banderas.'::text),
