(321505,35723,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона зазвичай їсть солодкі капкейки сама, але зараз ... у двері.'::text,'стукає'::text,'стукає'::text,NULL::text,'Вона зазвичай їсть солодкі капкейки сама, але зараз стукає у двері.'::text),
(321504,35723,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente ella come cupcakes dulces sola, pero ahora ... a la puerta.'::text,'está llamando'::text,'llama'::text,NULL::text,'Normalmente ella come cupcakes dulces sola, pero ahora está llamando a la puerta.'::text),
