(311457,34607,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der leere Park ist ... als die belebte Straße.'::text,'ruhiger'::text,'ruhiger'::text,'am ruhigsten'::text,'Der leere Park ist ruhiger als die belebte Straße.'::text),
