(300859,33429,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, кажуть, він ... на підлозі з сильною травмою.'::text,'сидить'::text,'сидить'::text,'сидить'::text,'Коротше, кажуть, він сидить на підлозі з сильною травмою.'::text),
(300858,33429,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues parece que él ... en el suelo con una herida grande.'::text,'está sentado'::text,'se sienta'::text,'está sentado'::text,'Vale, pues parece que él está sentado en el suelo con una herida grande.'::text),
(300857,33429,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, apparemment il ... par terre avec une grosse blessure.'::text,'est assis'::text,'s''assoit'::text,'est assis'::text,'Bon, apparemment il est assis par terre avec une grosse blessure.'::text),
(300860,33429,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, anlaşılan o büyük bir yarayla yerde ...'::text,'oturuyor'::text,'oturur'::text,'oturuyor'::text,'Tamam, anlaşılan o büyük bir yarayla yerde oturuyor.'::text),
(300861,33429,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval állítólag ő ... a földön egy nagy sérüléssel.'::text,'ül'::text,'ül'::text,'ül'::text,'Oké, szóval állítólag ő ül a földön egy nagy sérüléssel.'::text),
(302466,33608,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Wind ist verrückt! Ich glaube, dass sein Drachen für immer ...!'::text,'davonfliegen wird'::text,'davonfliegt'::text,'davonflog'::text,'Der Wind ist verrückt! Ich glaube, dass sein Drachen für immer davonfliegen wird!'::text),
(302470,33608,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вітер шалений! Я думаю, його повітряний змій ... назавжди!'::text,'відлетить'::text,'відлітає'::text,'відлетів'::text,'Вітер шалений! Я думаю, його повітряний змій відлетить назавжди!'::text),
(302469,33608,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El viento está loco! ¡Yo creo que su cometa ... para siempre!'::text,'saldrá volando'::text,'sale volando'::text,'salió volando'::text,'¡El viento está loco! ¡Yo creo que su cometa saldrá volando para siempre!'::text),
(302468,33608,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le vent est fou ! Je crois que son cerf-volant ... pour toujours !'::text,'s''envolera'::text,'s''envole'::text,'s''est envolé'::text,'Le vent est fou ! Je crois que son cerf-volant s''envolera pour toujours !'::text),
(302471,33608,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rüzgâr çılgın gibi! Bence uçurtması sonsuza dek ...!'::text,'uçup gidecek'::text,'uçup gider'::text,'uçup gitti'::text,'Rüzgâr çılgın gibi! Bence uçurtması sonsuza dek uçup gidecek!'::text),
(302472,33608,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őrült a szél! Szerintem a sárkánya örökre ...!'::text,'el fog repülni'::text,'elrepül'::text,'elrepült'::text,'Őrült a szél! Szerintem a sárkánya örökre el fog repülni!'::text),
(295068,32786,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... sich in der belebten Gasse auf den Ball konzentrieren.'::text,'kann'::text,'kann'::text,'ist'::text,'Er kann sich in der belebten Gasse auf den Ball konzentrieren.'::text),
(295072,32786,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... зосередитися на м''ячі у людному провулку.'::text,'може'::text,'може'::text,'є'::text,'Він може зосередитися на м''ячі у людному провулку.'::text),
(295071,32786,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... concentrarse en la pelota en el callejón concurrido.'::text,'puede'::text,'puede'::text,'está'::text,'Él puede concentrarse en la pelota en el callejón concurrido.'::text),
(295070,32786,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... se concentrer sur la balle dans la ruelle animée.'::text,'peut'::text,'peut'::text,'est'::text,'Il peut se concentrer sur la balle dans la ruelle animée.'::text),
(295073,32786,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kalabalık sokakta topa ...'::text,'odaklanabilir'::text,'odaklanabilir'::text,NULL::text,'O kalabalık sokakta topa odaklanabilir.'::text),
(295074,32786,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... a labdára koncentrálni a zsúfolt sikátorban.'::text,'tud'::text,'tud'::text,'van'::text,'Ő tud a labdára koncentrálni a zsúfolt sikátorban.'::text),
(308118,34236,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann mit dem Bilderbuch ist auch ... Elternteil.'::text,'ein'::text,'der'::text,'ein'::text,'Der Mann mit dem Bilderbuch ist auch ein Elternteil.'::text),
(308122,34236,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік із книжкою з картинками теж ... батько.'::text,''::text,NULL::text,NULL::text,'Чоловік із книжкою з картинками теж батько.'::text),
(308121,34236,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre del libro ilustrado también es ... padre.'::text,'un'::text,'el'::text,'un'::text,'El hombre del libro ilustrado también es un padre.'::text),
(308120,34236,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme au livre d''images est aussi ... parent.'::text,'un'::text,'le'::text,'un'::text,'L''homme au livre d''images est aussi un parent.'::text),
(308123,34236,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Resimli kitaplı adam da ... ebeveyn.'::text,'bir'::text,NULL::text,'bir'::text,'Resimli kitaplı adam da bir ebeveyn.'::text),
(308124,34236,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A képeskönyves férfi is ... szülő.'::text,'egy'::text,'a'::text,'egy'::text,'A képeskönyves férfi is egy szülő.'::text),
(308154,34240,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Eltern sind total erschöpft, ... die Kinder wollen wieder auf die Schaukeln!'::text,'aber'::text,'also'::text,'weil'::text,'Die Eltern sind total erschöpft, aber die Kinder wollen wieder auf die Schaukeln!'::text),
(308158,34240,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Батьки геть виснажені, ... діти знову хочуть на гойдалки!'::text,'але'::text,'тому'::text,'бо'::text,'Батьки геть виснажені, але діти знову хочуть на гойдалки!'::text),
(308157,34240,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Los padres están totalmente agotados, ... los niños quieren volver a los columpios!'::text,'pero'::text,'así que'::text,'porque'::text,'¡Los padres están totalmente agotados, pero los niños quieren volver a los columpios!'::text),
(308156,34240,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les parents sont complètement épuisés, ... les enfants veulent encore les balançoires !'::text,'mais'::text,'donc'::text,'parce que'::text,'Les parents sont complètement épuisés, mais les enfants veulent encore les balançoires !'::text),
(308159,34240,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Anne babalar tamamen bitkin, ... çocuklar yine salıncak istiyor!'::text,'ama'::text,'bu yüzden'::text,'çünkü'::text,'Anne babalar tamamen bitkin, ama çocuklar yine salıncak istiyor!'::text),
(308160,34240,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szülők teljesen ki vannak merülve, ... a gyerekek megint hintázni akarnak!'::text,'de'::text,'ezért'::text,'mert'::text,'A szülők teljesen ki vannak merülve, de a gyerekek megint hintázni akarnak!'::text),
(324390,36044,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oh nein! Der Zug ... keinen Platz für meinen riesigen Koffer!'::text,'hat'::text,'haben'::text,'hat'::text,'Oh nein! Der Zug hat keinen Platz für meinen riesigen Koffer!'::text),
(324394,36044,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'О ні! Потяг ... місця для моєї величезної валізи!'::text,'не має'::text,'не мати'::text,'не має'::text,'О ні! Потяг не має місця для моєї величезної валізи!'::text),
(324393,36044,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Oh, no! ¡El tren no ... sitio para mi maleta enorme!'::text,'tiene'::text,'tienen'::text,'tiene'::text,'¡Oh, no! ¡El tren no tiene sitio para mi maleta enorme!'::text),
(324392,36044,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oh non ! Le train ... pas de place pour ma valise énorme !'::text,'n''a'::text,'n''ont'::text,'n''a'::text,'Oh non ! Le train n''a pas de place pour ma valise énorme !'::text),
(324395,36044,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olamaz! Trende kocaman bavulum için yer ...!'::text,'yok'::text,'yok'::text,'yok'::text,'Olamaz! Trende kocaman bavulum için yer yok!'::text),
(324396,36044,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jaj, ne! A vonaton ... hely a hatalmas bőröndömnek!'::text,'nincs'::text,'nincs'::text,'nincs'::text,'Jaj, ne! A vonaton nincs hely a hatalmas bőröndömnek!'::text),
(324453,36051,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Auf der Gepäckablage im Zug ... jetzt ein großer Koffer.'::text,'ist'::text,'sind'::text,'sein'::text,'Auf der Gepäckablage im Zug ist jetzt ein großer Koffer.'::text),
(324457,36051,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На полиці в потязі зараз ... велика валіза.'::text,'є'::text,'є'::text,'бути'::text,'На полиці в потязі зараз є велика валіза.'::text),
(324456,36051,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora ... una maleta grande en el portaequipajes del tren.'::text,'hay'::text,'hay'::text,'hay'::text,'Ahora hay una maleta grande en el portaequipajes del tren.'::text),
(324455,36051,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Maintenant, ... une grande valise sur le porte-bagages du train.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Maintenant, il y a une grande valise sur le porte-bagages du train.'::text),
(324458,36051,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şimdi trenin bagaj rafında büyük bir bavul ...'::text,'var'::text,'var'::text,'olmak'::text,'Şimdi trenin bagaj rafında büyük bir bavul var.'::text),
(324459,36051,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Most ... egy nagy bőrönd a vonat csomagtartóján.'::text,'van'::text,'vannak'::text,'lenni'::text,'Most van egy nagy bőrönd a vonat csomagtartóján.'::text),
(308658,34296,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zwei ... reichen sich für den Frieden die Hände.'::text,'Soldaten'::text,'Soldat'::text,'Soldaten'::text,'Zwei Soldaten reichen sich für den Frieden die Hände.'::text),
(308662,34296,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Двоє ... тиснуть руки заради миру.'::text,'солдатів'::text,'солдат'::text,'солдатів'::text,'Двоє солдатів тиснуть руки заради миру.'::text),
(308661,34296,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dos ... se dan la mano por la paz.'::text,'soldados'::text,'soldado'::text,'soldados'::text,'Dos soldados se dan la mano por la paz.'::text),
(308660,34296,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deux ... se serrent la main pour la paix.'::text,'soldats'::text,'soldat'::text,'soldats'::text,'Deux soldats se serrent la main pour la paix.'::text),
(308663,34296,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki ... barış için tokalaşıyor.'::text,'asker'::text,'asker'::text,'askerler'::text,'İki asker barış için tokalaşıyor.'::text),
(308664,34296,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Két ... kezet fog a békéért.'::text,'katona'::text,'katona'::text,'katona'::text,'Két katona kezet fog a békéért.'::text),
(324489,36055,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seine Straßenbahn kommt jeden Morgen ... 8:15.'::text,'um'::text,'am'::text,'im'::text,'Seine Straßenbahn kommt jeden Morgen um 8:15.'::text),
(324493,36055,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його трамвай приходить щоранку ... 8:15.'::text,'о'::text,'на'::text,'у'::text,'Його трамвай приходить щоранку о 8:15.'::text),
(324492,36055,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su tranvía llega cada mañana ... las 8:15.'::text,'a'::text,'sobre'::text,'en'::text,'Su tranvía llega cada mañana a las 8:15.'::text),
(324491,36055,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son tram arrive tous les matins ... 8 h 15.'::text,'à'::text,'sur'::text,'dans'::text,'Son tram arrive tous les matins à 8 h 15.'::text),
(324494,36055,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun tramvayı her sabah saat 8:15 ... geliyor.'::text,''::text,NULL::text,NULL::text,'Onun tramvayı her sabah saat 8:15 geliyor.'::text),
(324495,36055,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A villamosa minden reggel ... jön.'::text,'8:15-kor'::text,'8:15-ön'::text,'8:15-ben'::text,'A villamosa minden reggel 8:15-kor jön.'::text),
(324507,36057,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, er fährt sonst mit der Straßenbahn, aber heute ... er schnell zu Fuß, irgendwie.'::text,'geht'::text,'geht'::text,NULL::text,'Digga, er fährt sonst mit der Straßenbahn, aber heute geht er schnell zu Fuß, irgendwie.'::text),
(324511,36057,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він зазвичай їздить трамваєм, але сьогодні ... швидко пішки, якщо чесно.'::text,'іде'::text,'іде'::text,NULL::text,'Бро, він зазвичай їздить трамваєм, але сьогодні іде швидко пішки, якщо чесно.'::text),
(324510,36057,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, él normalmente coge el tranvía, pero hoy ... rápido, la verdad.'::text,'está caminando'::text,'camina'::text,NULL::text,'Bro, él normalmente coge el tranvía, pero hoy está caminando rápido, la verdad.'::text),
(324509,36057,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, d''habitude il prend le tram, mais aujourd''hui il ... vite, genre.'::text,'est en train de marcher'::text,'marche'::text,NULL::text,'Frère, d''habitude il prend le tram, mais aujourd''hui il est en train de marcher vite, genre.'::text),
(324512,36057,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o genelde tramvaya biner ama bugün hızlı ..., açıkçası.'::text,'yürüyor'::text,'yürür'::text,NULL::text,'Kanka, o genelde tramvaya biner ama bugün hızlı yürüyor, açıkçası.'::text),
(324513,36057,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő általában villamossal jár, de ma gyorsan ..., amúgy.'::text,'gyalogol'::text,'gyalogol'::text,NULL::text,'Tesó, ő általában villamossal jár, de ma gyorsan gyalogol, amúgy.'::text),
(308766,34308,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Markt ist ... Samstag voller Leute! Nie wieder!'::text,'am'::text,'um'::text,'im'::text,'Der Markt ist am Samstag voller Leute! Nie wieder!'::text),
(308770,34308,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ринок ... суботу повний людей! Більше ніколи!'::text,'у'::text,'о'::text,'у'::text,'Ринок у суботу повний людей! Більше ніколи!'::text),
(308769,34308,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El mercado está lleno de gente ... el sábado! ¡Nunca más!'::text,''::text,'a'::text,'en'::text,'¡El mercado está lleno de gente el sábado! ¡Nunca más!'::text),
(308768,34308,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le marché est plein de monde ... samedi ! Plus jamais !'::text,''::text,'à'::text,'dans'::text,'Le marché est plein de monde samedi ! Plus jamais !'::text),
(308771,34308,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çarşı cumartesi ... insanla dolu! Bir daha asla!'::text,''::text,NULL::text,NULL::text,'Çarşı cumartesi insanla dolu! Bir daha asla!'::text),
(308772,34308,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A piac ... tele van emberekkel! Soha többé!'::text,'szombaton'::text,'szombatkor'::text,'szombatban'::text,'A piac szombaton tele van emberekkel! Soha többé!'::text),
(308784,34310,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, tausend Leute ... den Zebrastreifen in einer Minute.'::text,'überquerten'::text,'überqueren'::text,'überquerend'::text,'Bestie, ich hab gehört, tausend Leute überquerten den Zebrastreifen in einer Minute.'::text),
(308788,34310,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що тисяча людей ... перехід за одну хвилину.'::text,'перейшла'::text,'переходить'::text,'переходячи'::text,'Подруго, я чула, що тисяча людей перейшла перехід за одну хвилину.'::text),
(308787,34310,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, yo he oído que mil personas ... el paso de cebra en un minuto.'::text,'cruzaron'::text,'cruzan'::text,'cruzando'::text,'Amiga, yo he oído que mil personas cruzaron el paso de cebra en un minuto.'::text),
(308786,34310,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, j''ai entendu que mille personnes ... le passage piéton en une minute.'::text,'ont traversé'::text,'traversent'::text,'traversant'::text,'Ma belle, j''ai entendu que mille personnes ont traversé le passage piéton en une minute.'::text),
(308789,34310,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kankam, ben duydum ki bin kişi yaya geçidini bir dakikada ...'::text,'geçti'::text,'geçer'::text,'geçerek'::text,'Kankam, ben duydum ki bin kişi yaya geçidini bir dakikada geçti.'::text),
(308790,34310,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, én azt hallottam, hogy ezer ember egy perc alatt ... a zebrán.'::text,'átkelt'::text,'átkel'::text,'átkelő'::text,'Csajszi, én azt hallottam, hogy ezer ember egy perc alatt átkelt a zebrán.'::text),
(305652,33962,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Heute Morgen sind nicht ... Leute da, und ehrlich, du bist so ruhig.'::text,'viele'::text,'viel'::text,'einige'::text,'Heute Morgen sind nicht viele Leute da, und ehrlich, du bist so ruhig.'::text),
(305656,33962,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сьогодні вранці тут немає ... людей, і, чесно, ти така спокійна.'::text,'багато'::text,'багато'::text,'якихось'::text,'Сьогодні вранці тут немає багато людей, і, чесно, ти така спокійна.'::text),
(305655,33962,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esta mañana no hay ... personas, y sinceramente, tú estás tan tranquila.'::text,'muchas'::text,'mucha'::text,'algunas'::text,'Esta mañana no hay muchas personas, y sinceramente, tú estás tan tranquila.'::text),
(305654,33962,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il n''y a pas ... monde ce matin, et franchement, tu es tellement calme.'::text,'beaucoup de'::text,'beaucoup de'::text,'du'::text,'Il n''y a pas beaucoup de monde ce matin, et franchement, tu es tellement calme.'::text),
(305657,33962,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sabah ... insan yok ve açıkçası sen çok sakinsin.'::text,'çok'::text,'çok'::text,'bazı'::text,'Bu sabah çok insan yok ve açıkçası sen çok sakinsin.'::text),
(305658,33962,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma reggel nincs ... ember, és őszintén, te olyan nyugodt vagy.'::text,'sok'::text,'sok'::text,'néhány'::text,'Ma reggel nincs sok ember, és őszintén, te olyan nyugodt vagy.'::text),
(309144,34350,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Apotheke hat ... Nacht geöffnet, also ist sie nicht geschlossen.'::text,'in der'::text,'in der'::text,'an der'::text,'Die Apotheke hat in der Nacht geöffnet, also ist sie nicht geschlossen.'::text),
