(319282,35476,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, бро, це ... величезна станція, а не маленька зупинка.'::text,''::text,NULL::text,NULL::text,'Йо, бро, це величезна станція, а не маленька зупинка.'::text),
(319281,35476,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eh, bro, esto es ... estación enorme, no una parada pequeña.'::text,'una'::text,'una'::text,'la'::text,'Eh, bro, esto es una estación enorme, no una parada pequeña.'::text),
(319280,35476,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo frère, c''est ... gare énorme, pas un petit arrêt.'::text,'une'::text,'une'::text,'la'::text,'Yo frère, c''est une gare énorme, pas un petit arrêt.'::text),
(319283,35476,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu ... dev istasyon, küçük bir durak değil.'::text,'bir'::text,'bir'::text,NULL::text,'Kanka, bu bir dev istasyon, küçük bir durak değil.'::text),
(319284,35476,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ez ... hatalmas állomás, nem egy kis megálló.'::text,'egy'::text,'egy'::text,'a'::text,'Tesó, ez egy hatalmas állomás, nem egy kis megálló.'::text),
(319323,35481,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Also, sie hat mir erzählt, am Bahnhof waren so ... Leute.'::text,'viele'::text,'viel'::text,'eine Menge'::text,'Also, sie hat mir erzählt, am Bahnhof waren so viele Leute.'::text),
(319327,35481,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, вона сказала мені, що на станції було так ... людей.'::text,'багато'::text,'багато'::text,'багато'::text,'Коротше, вона сказала мені, що на станції було так багато людей.'::text),
(319326,35481,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues ella me dijo que había ... personas en la estación.'::text,'tantas'::text,'tanta'::text,'un montón de'::text,'Vale, pues ella me dijo que había tantas personas en la estación.'::text),
(319325,35481,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, elle m''a dit qu''il y avait ... monde à la gare.'::text,'tellement de'::text,'tellement de'::text,'plein de'::text,'Bon, elle m''a dit qu''il y avait tellement de monde à la gare.'::text),
(319328,35481,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, o bana istasyonda o kadar ... insan olduğunu söyledi.'::text,'çok'::text,'çok'::text,'çok'::text,'Tamam, o bana istasyonda o kadar çok insan olduğunu söyledi.'::text),
(319329,35481,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval ő azt mondta, hogy olyan ... ember volt az állomáson.'::text,'sok'::text,'sok'::text,'rengeteg'::text,'Oké, szóval ő azt mondta, hogy olyan sok ember volt az állomáson.'::text),
(325659,36185,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, Digga, das ist keine Jacke, das ist ... Weste.'::text,'eine'::text,'eine'::text,'die'::text,'Nee, Digga, das ist keine Jacke, das ist eine Weste.'::text),
(325663,36185,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, це не куртка, це ... жилетка.'::text,''::text,NULL::text,NULL::text,'Не, бро, це не куртка, це жилетка.'::text),
(325662,36185,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Que no, bro, no es una chaqueta, es ... chaleco.'::text,'un'::text,'un'::text,'el'::text,'Que no, bro, no es una chaqueta, es un chaleco.'::text),
(325661,36185,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non frère, c''est pas une veste, c''est ... gilet.'::text,'un'::text,'un'::text,'le'::text,'Non frère, c''est pas une veste, c''est un gilet.'::text),
(325664,36185,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, bu ceket değil, bu ... yelek.'::text,'bir'::text,'bir'::text,NULL::text,'Yok kanka, bu ceket değil, bu bir yelek.'::text),
(325665,36185,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dehogy, tesó, ez nem dzseki, ez ... mellény.'::text,'egy'::text,'egy'::text,'a'::text,'Dehogy, tesó, ez nem dzseki, ez egy mellény.'::text),
(325686,36188,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine Weste hat keine Ärmel, also braucht sie weniger ... als eine Jacke.'::text,'Stoff'::text,'Stoff'::text,'einen Stoff'::text,'Eine Weste hat keine Ärmel, also braucht sie weniger Stoff als eine Jacke.'::text),
(325690,36188,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жилетка не має рукавів, тож їй треба менше ..., ніж куртці.'::text,'матеріалу'::text,'матеріалів'::text,'матеріалу'::text,'Жилетка не має рукавів, тож їй треба менше матеріалу, ніж куртці.'::text),
(325689,36188,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un chaleco no tiene mangas, así que necesita menos ... que una chaqueta.'::text,'material'::text,'material'::text,'un material'::text,'Un chaleco no tiene mangas, así que necesita menos material que una chaqueta.'::text),
(325688,36188,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un gilet n''a pas de manches, donc il lui faut moins de ... qu''une veste.'::text,'tissu'::text,'tissu'::text,'un tissu'::text,'Un gilet n''a pas de manches, donc il lui faut moins de tissu qu''une veste.'::text),
(325691,36188,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yeleğin kolu yok, bu yüzden ceketten daha az ... gerekir.'::text,'malzeme'::text,'malzemeler'::text,'bir malzeme'::text,'Yeleğin kolu yok, bu yüzden ceketten daha az malzeme gerekir.'::text),
(325692,36188,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A mellénynek nincs ujja, ezért kevesebb ... kell hozzá, mint egy dzsekihez.'::text,'anyag'::text,'anyag'::text,'egy anyag'::text,'A mellénynek nincs ujja, ezért kevesebb anyag kell hozzá, mint egy dzsekihez.'::text),
(313716,34858,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hilfe! Etwas ist ... diesem dunklen Raum!'::text,'in'::text,'auf'::text,'an'::text,'Hilfe! Etwas ist in diesem dunklen Raum!'::text),
(313720,34858,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рятуйте! Щось є ... цій темній кімнаті!'::text,'у'::text,'на'::text,'біля'::text,'Рятуйте! Щось є у цій темній кімнаті!'::text),
(313719,34858,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Socorro! ¡Hay algo ... esta habitación oscura!'::text,'en'::text,'sobre'::text,'a'::text,'¡Socorro! ¡Hay algo en esta habitación oscura!'::text),
(313718,34858,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au secours ! Il y a quelque chose ... cette pièce sombre !'::text,'dans'::text,'sur'::text,'à'::text,'Au secours ! Il y a quelque chose dans cette pièce sombre !'::text),
(313721,34858,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İmdat! Bu karanlık odanın ... bir şey var!'::text,'içinde'::text,'üstünde'::text,NULL::text,'İmdat! Bu karanlık odanın içinde bir şey var!'::text),
(313722,34858,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Segítség! Valami van ebben a sötét ...!'::text,'szobában'::text,'szobán'::text,'szobánál'::text,'Segítség! Valami van ebben a sötét szobában!'::text),
(313779,34865,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Raum ist dunkel, ... geht sie nicht hinein.'::text,'also'::text,'aber'::text,'weil'::text,'Der Raum ist dunkel, also geht sie nicht hinein.'::text),
(313783,34865,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кімната темна, ... вона не заходить.'::text,'тому'::text,'але'::text,'бо'::text,'Кімната темна, тому вона не заходить.'::text),
(313782,34865,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La habitación está oscura, ... ella no entra.'::text,'así que'::text,'pero'::text,'porque'::text,'La habitación está oscura, así que ella no entra.'::text),
(313781,34865,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pièce est sombre, ... elle n''entre pas.'::text,'donc'::text,'mais'::text,'parce que'::text,'La pièce est sombre, donc elle n''entre pas.'::text),
(313784,34865,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oda karanlık, ... o içeri girmiyor.'::text,'bu yüzden'::text,'ama'::text,'çünkü'::text,'Oda karanlık, bu yüzden o içeri girmiyor.'::text),
(313785,34865,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szoba sötét, ... ő nem megy be.'::text,'ezért'::text,'de'::text,'mert'::text,'A szoba sötét, ezért ő nem megy be.'::text),
(313824,34870,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sitzt auf dem königlichen Thron? Der König.'::text,'Wer'::text,'Wo'::text,'Was'::text,'Wer sitzt auf dem königlichen Thron? Der König.'::text),
(313828,34870,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... сидить на королівському троні? Король.'::text,'Хто'::text,'Де'::text,'Що'::text,'Хто сидить на королівському троні? Король.'::text),
(313827,34870,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... se sienta en el trono real? El rey.'::text,'Quién'::text,'Dónde'::text,'Qué'::text,'¿Quién se sienta en el trono real? El rey.'::text),
(313826,34870,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... est assis sur le trône royal ? Le roi.'::text,'Qui'::text,'Où'::text,'Que'::text,'Qui est assis sur le trône royal ? Le roi.'::text),
(313829,34870,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kraliyet tahtında ... oturuyor? Kral.'::text,'kim'::text,'nerede'::text,'ne'::text,'Kraliyet tahtında kim oturuyor? Kral.'::text),
(313830,34870,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ül a királyi trónon? A király.'::text,'Ki'::text,'Hol'::text,'Mi'::text,'Ki ül a királyi trónon? A király.'::text),
(313833,34871,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, ich hab gehört, die königlichen Diener ... ihm ein ganzes Tablett voller Essen.'::text,'brachten'::text,'brachten'::text,'bringt'::text,'Mädel, ich hab gehört, die königlichen Diener brachten ihm ein ganzes Tablett voller Essen.'::text),
(313837,34871,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що королівські слуги ... йому цілу тацю їжі.'::text,'принесли'::text,'принесли'::text,'приносить'::text,'Подруго, я чула, що королівські слуги принесли йому цілу тацю їжі.'::text),
(313836,34871,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, yo he oído que los sirvientes reales le ... una bandeja entera de comida.'::text,'trajeron'::text,'trajeron'::text,'trae'::text,'Tía, yo he oído que los sirvientes reales le trajeron una bandeja entera de comida.'::text),
(313835,34871,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, j''ai entendu dire que les serviteurs royaux lui ... un plateau entier de nourriture.'::text,'ont apporté'::text,'ont apporté'::text,'apporte'::text,'Ma belle, j''ai entendu dire que les serviteurs royaux lui ont apporté un plateau entier de nourriture.'::text),
(313838,34871,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, ben duydum ki kraliyet hizmetkârları ona koca bir tepsi yemek ...'::text,'getirdi'::text,'getirdi'::text,'getirir'::text,'Kızım, ben duydum ki kraliyet hizmetkârları ona koca bir tepsi yemek getirdi.'::text),
(313839,34871,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, én azt hallottam, hogy a királyi szolgák ... neki egy egész tálca ételt.'::text,'hoztak'::text,'hoztak'::text,'hoz'::text,'Csajszi, én azt hallottam, hogy a királyi szolgák hoztak neki egy egész tálca ételt.'::text),
(294600,32734,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... beendet sie das Rennen? An der blauen Linie.'::text,'Wo'::text,'Wer'::text,'Was'::text,'Wo beendet sie das Rennen? An der blauen Linie.'::text),
(294604,32734,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... вона завершує забіг? Біля синьої лінії.'::text,'Де'::text,'Хто'::text,'Що'::text,'Де вона завершує забіг? Біля синьої лінії.'::text),
(294603,32734,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... termina ella la carrera? En la línea azul.'::text,'Dónde'::text,'Quién'::text,'Qué'::text,'¿Dónde termina ella la carrera? En la línea azul.'::text),
(294602,32734,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... termine-t-elle la course ? À la ligne bleue.'::text,'Où'::text,'Qui'::text,'Que'::text,'Où termine-t-elle la course ? À la ligne bleue.'::text),
(294605,32734,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O yarışı ... bitiriyor? Mavi çizgide.'::text,'nerede'::text,'kim'::text,'ne'::text,'O yarışı nerede bitiriyor? Mavi çizgide.'::text),
(294606,32734,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... fejezi be ő a versenyt? A kék vonalnál.'::text,'Hol'::text,'Ki'::text,'Mi'::text,'Hol fejezi be ő a versenyt? A kék vonalnál.'::text),
(294645,32739,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ist müde, ... sie beendet das Rennen.'::text,'aber'::text,'also'::text,'weil'::text,'Sie ist müde, aber sie beendet das Rennen.'::text),
(294649,32739,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона втомлена, ... завершує забіг.'::text,'але'::text,'тому'::text,'бо'::text,'Вона втомлена, але завершує забіг.'::text),
(294648,32739,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella está cansada, ... termina la carrera.'::text,'pero'::text,'así que'::text,'porque'::text,'Ella está cansada, pero termina la carrera.'::text),
(294647,32739,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle est fatiguée, ... elle termine la course.'::text,'mais'::text,'donc'::text,'parce que'::text,'Elle est fatiguée, mais elle termine la course.'::text),
(294650,32739,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O yorgun ... yarışı bitiriyor.'::text,'ama'::text,'bu yüzden'::text,'çünkü'::text,'O yorgun ama yarışı bitiriyor.'::text),
(294651,32739,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő fáradt, ... befejezi a versenyt.'::text,'de'::text,'ezért'::text,'mert'::text,'Ő fáradt, de befejezi a versenyt.'::text),
(317775,35309,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es schneit stark, also ... sie durch tiefen Schnee gehen.'::text,'muss'::text,'muss'::text,'sollte'::text,'Es schneit stark, also muss sie durch tiefen Schnee gehen.'::text),
(317779,35309,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сильно сніжить, тож вона ... йти глибоким снігом.'::text,'має'::text,'мусить'::text,'мала б'::text,'Сильно сніжить, тож вона має йти глибоким снігом.'::text),
(317778,35309,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está nevando mucho, así que ella ... caminar por la nieve profunda.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Está nevando mucho, así que ella tiene que caminar por la nieve profunda.'::text),
(317777,35309,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il neige fort, donc elle ... marcher dans la neige profonde.'::text,'doit'::text,'doit'::text,'devrait'::text,'Il neige fort, donc elle doit marcher dans la neige profonde.'::text),
(317780,35309,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kar çok yağıyor, bu yüzden o derin karda ...'::text,'yürümek zorunda'::text,'yürümeli'::text,'yürümeli'::text,'Kar çok yağıyor, bu yüzden o derin karda yürümek zorunda.'::text),
(317781,35309,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Erősen havazik, ezért neki mély hóban ... gyalogolnia.'::text,'kell'::text,'kell'::text,'kellene'::text,'Erősen havazik, ezért neki mély hóban kell gyalogolnia.'::text),
(319089,35455,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schau dir ... Sterne über dem Lagerfeuer an.'::text,'jene'::text,'jenen'::text,'diesen'::text,'Schau dir jene Sterne über dem Lagerfeuer an.'::text),
(319093,35455,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подивись на ... зорі над вогнищем.'::text,'ті'::text,'ту'::text,'цю'::text,'Подивись на ті зорі над вогнищем.'::text),
(319092,35455,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mira ... estrellas sobre la hoguera.'::text,'esas'::text,'esa'::text,'esta'::text,'Mira esas estrellas sobre la hoguera.'::text),
(319091,35455,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Regarde ... étoiles au-dessus du feu de camp.'::text,'ces'::text,'cette'::text,'cette'::text,'Regarde ces étoiles au-dessus du feu de camp.'::text),
(319094,35455,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kamp ateşinin üstündeki ... yıldızlara bak.'::text,'şu'::text,'şu'::text,'bu'::text,'Kamp ateşinin üstündeki şu yıldızlara bak.'::text),
(319095,35455,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nézd ... csillagokat a tábortűz fölött.'::text,'azokat a'::text,'azt a'::text,'ezt a'::text,'Nézd azokat a csillagokat a tábortűz fölött.'::text),
(319125,35459,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir gesagt, er ... gerade Tee unter den Sternen.'::text,'trinkt'::text,'trinkt'::text,'trinkt'::text,'Hör zu, er hat mir gesagt, er trinkt gerade Tee unter den Sternen.'::text),
(319129,35459,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав мені, що саме зараз ... чай під зорями.'::text,'п''є'::text,'п''є'::text,'п''є'::text,'Слухай, він сказав мені, що саме зараз п''є чай під зорями.'::text),
(319128,35459,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, él me dijo que ahora mismo ... té bajo las estrellas.'::text,'está tomando'::text,'toma'::text,'está tomando'::text,'Oye, él me dijo que ahora mismo está tomando té bajo las estrellas.'::text),
(319127,35459,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit qu''il ... du thé sous les étoiles en ce moment.'::text,'est en train de boire'::text,'boit'::text,'est en train de boire'::text,'Écoute, il m''a dit qu''il est en train de boire du thé sous les étoiles en ce moment.'::text),
(319130,35459,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, o bana dedi ki şu an yıldızların altında çay ...'::text,'içiyor'::text,'içer'::text,'içiyor'::text,'Dinle, o bana dedi ki şu an yıldızların altında çay içiyor.'::text),
(319131,35459,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, ő azt mondta, hogy épp most teát ... a csillagok alatt.'::text,'iszik'::text,'iszik'::text,'iszik'::text,'Figyelj, ő azt mondta, hogy épp most teát iszik a csillagok alatt.'::text),
(312537,34727,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oh nein! Da ... keine kostenlosen Motorroller, nur Motorroller zum Mieten!'::text,'sind'::text,'ist'::text,'sein'::text,'Oh nein! Da sind keine kostenlosen Motorroller, nur Motorroller zum Mieten!'::text),
(312541,34727,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'О ні! Тут ... безкоштовних скутерів, тільки скутери в оренду!'::text,'немає'::text,'немає'::text,'не бути'::text,'О ні! Тут немає безкоштовних скутерів, тільки скутери в оренду!'::text),
(312540,34727,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Oh, no! ¡... escúteres gratis, solo escúteres de alquiler!'::text,'No hay'::text,'No hay'::text,'No hay'::text,'¡Oh, no! ¡No hay escúteres gratis, solo escúteres de alquiler!'::text),
(312539,34727,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oh non ! ... pas de scooters gratuits, seulement des scooters à louer !'::text,'Il n''y a'::text,'Il n''y a'::text,'Il n''y a'::text,'Oh non ! Il n''y a pas de scooters gratuits, seulement des scooters à louer !'::text),
(312542,34727,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olamaz! Bedava scooter ..., sadece kiralık scooter var!'::text,'yok'::text,'yok'::text,'olmak'::text,'Olamaz! Bedava scooter yok, sadece kiralık scooter var!'::text),
(312543,34727,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jaj, ne! ... ingyenes robogók, csak bérelhető robogók!'::text,'Nincsenek'::text,'Nincs'::text,'Lenni'::text,'Jaj, ne! Nincsenek ingyenes robogók, csak bérelhető robogók!'::text),
(326325,36259,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... jeden Abend die schwarzen Pfannen.'::text,'spült'::text,'spülen'::text,'spült'::text,'Er spült jeden Abend die schwarzen Pfannen.'::text),
(326329,36259,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він щовечора ... чорні сковорідки.'::text,'миє'::text,'мити'::text,'миє'::text,'Він щовечора миє чорні сковорідки.'::text),
(326328,36259,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... las sartenes negras todas las noches.'::text,'friega'::text,'fregar'::text,'friega'::text,'Él friega las sartenes negras todas las noches.'::text),
