(326330,36259,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O her akşam siyah tavaları ...'::text,'yıkar'::text,'yıkamak'::text,'yıkar'::text,'O her akşam siyah tavaları yıkar.'::text),
(326331,36259,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő minden este ... a fekete serpenyőket.'::text,'elmossa'::text,'elmosni'::text,'elmossa'::text,'Ő minden este elmossa a fekete serpenyőket.'::text),
(325137,36127,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... so schnell, während du telefonierst. Beeindruckend.'::text,'tippst'::text,'tippt'::text,'tippend'::text,'Du tippst so schnell, während du telefonierst. Beeindruckend.'::text),
(325141,36127,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... так швидко, поки говориш по телефону. Вражає.'::text,'друкуєш'::text,'друкує'::text,'друкуючи'::text,'Ти друкуєш так швидко, поки говориш по телефону. Вражає.'::text),
(325140,36127,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... tan rápido mientras hablas por teléfono. Impresionante.'::text,'escribes'::text,'escribe'::text,'escribiendo'::text,'Tú escribes tan rápido mientras hablas por teléfono. Impresionante.'::text),
(325139,36127,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... tellement vite pendant que tu parles au téléphone. Impressionnant.'::text,'tapes'::text,'tape'::text,'tapant'::text,'Tu tapes tellement vite pendant que tu parles au téléphone. Impressionnant.'::text),
(325142,36127,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen telefonda konuşurken o kadar hızlı ...! Etkileyici.'::text,'yazarsın'::text,'yazar'::text,'yazarak'::text,'Sen telefonda konuşurken o kadar hızlı yazarsın! Etkileyici.'::text),
(325143,36127,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te olyan gyorsan ..., miközben telefonálsz. Lenyűgöző.'::text,'gépelsz'::text,'gépel'::text,'gépelő'::text,'Te olyan gyorsan gépelsz, miközben telefonálsz. Lenyűgöző.'::text),
(325164,36130,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein ruhiger Tag, klar: Sie ... heute Nachmittag fünfzig E-Mails tippen.'::text,'wird'::text,'wird'::text,'werden'::text,'Ein ruhiger Tag, klar: Sie wird heute Nachmittag fünfzig E-Mails tippen.'::text),
(325168,36130,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Спокійний день, звісно: вона сьогодні по обіді ... п''ятдесят імейлів.'::text,'збирається надрукувати'::text,'збирається надрукувати'::text,'збираються надрукувати'::text,'Спокійний день, звісно: вона сьогодні по обіді збирається надрукувати п''ятдесят імейлів.'::text),
(325167,36130,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un día tranquilo, obviamente: ella ... cincuenta correos esta tarde.'::text,'va a escribir'::text,'va a escribir'::text,'van a escribir'::text,'Un día tranquilo, obviamente: ella va a escribir cincuenta correos esta tarde.'::text),
(325166,36130,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une journée calme, évidemment : elle ... cinquante e-mails cet après-midi.'::text,'va taper'::text,'va taper'::text,'vont taper'::text,'Une journée calme, évidemment : elle va taper cinquante e-mails cet après-midi.'::text),
(325169,36130,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sakin bir gün tabii: o bu öğleden sonra elli e-posta ...'::text,'yazacak'::text,'yazacak'::text,'yazacaklar'::text,'Sakin bir gün tabii: o bu öğleden sonra elli e-posta yazacak.'::text),
(325170,36130,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyugis nap, persze: ő ma délután ötven e-mailt ... begépelni.'::text,'fog'::text,'fog'::text,'fognak'::text,'Nyugis nap, persze: ő ma délután ötven e-mailt fog begépelni.'::text),
(315030,35004,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, aber ihr ... die Senioren-Stars dieses Tanzkurses.'::text,'seid'::text,'ist'::text,'bin'::text,'Okay, aber ihr seid die Senioren-Stars dieses Tanzkurses.'::text),
(315034,35004,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Окей, але ви ... зірки старшого покоління в цьому танцювальному класі.'::text,'є'::text,'є'::text,'є'::text,'Окей, але ви є зірки старшого покоління в цьому танцювальному класі.'::text),
(315033,35004,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pero vosotros ... las estrellas sénior de esta clase de baile.'::text,'sois'::text,'es'::text,'soy'::text,'Vale, pero vosotros sois las estrellas sénior de esta clase de baile.'::text),
