(315036,35004,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, de ti ... ennek a tánctanfolyamnak a szenior sztárjai.'::text,'vagytok'::text,NULL::text,'vagyok'::text,'Oké, de ti vagytok ennek a tánctanfolyamnak a szenior sztárjai.'::text),
(315048,35006,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein fauler Tag, klar: Gestern ... der ältere Herr zehn Kilometer.'::text,'ging'::text,'geht'::text,'ging'::text,'Ein fauler Tag, klar: Gestern ging der ältere Herr zehn Kilometer.'::text),
(315052,35006,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лінивий день, звісно: учора літній чоловік ... десять кілометрів.'::text,'пройшов'::text,'проходить'::text,'пройшов'::text,'Лінивий день, звісно: учора літній чоловік пройшов десять кілометрів.'::text),
