(315050,35006,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une journée de flemme, évidemment : hier, le monsieur âgé ... dix kilomètres.'::text,'a marché'::text,'marche'::text,'a marché'::text,'Une journée de flemme, évidemment : hier, le monsieur âgé a marché dix kilomètres.'::text),
