(308318,34258,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, ... pas de partenaire plus smooth que toi.'::text,'il n''y a'::text,'il n''y a'::text,'il n''y a'::text,'Je vais pas mentir, il n''y a pas de partenaire plus smooth que toi.'::text),
