(309330,34370,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tökéletes terv: az egész falon csak egy fénykép ...'::text,'van'::text,'vannak'::text,'lenni'::text,'Tökéletes terv: az egész falon csak egy fénykép van.'::text),
(322437,35827,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Chef ruft auf dem Telefon an, also ... sie rangehen.'::text,'muss'::text,'muss'::text,'sollte'::text,'Ihr Chef ruft auf dem Telefon an, also muss sie rangehen.'::text),
