(322440,35827,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su jefe llama por teléfono, así que ella ... contestar.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Su jefe llama por teléfono, así que ella tiene que contestar.'::text),
(322439,35827,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son patron appelle sur le téléphone, donc elle ... répondre.'::text,'doit'::text,'doit'::text,'devrait'::text,'Son patron appelle sur le téléphone, donc elle doit répondre.'::text),
