(298137,33127,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie zielt mit ihrem Gewehr auf ... runde Scheiben.'::text,'fünf'::text,'fünfte'::text,'fünfte'::text,'Sie zielt mit ihrem Gewehr auf fünf runde Scheiben.'::text),
(298141,33127,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона цілиться з рушниці в ... круглих мішеней.'::text,'п''ять'::text,'п''яту'::text,'п''яту'::text,'Вона цілиться з рушниці в п''ять круглих мішеней.'::text),
(298140,33127,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella apunta con su arma a ... dianas redondas.'::text,'cinco'::text,'quintas'::text,'quintas'::text,'Ella apunta con su arma a cinco dianas redondas.'::text),
(298139,33127,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle vise ... cibles rondes avec son arme.'::text,'cinq'::text,'cinquièmes'::text,'cinquièmes'::text,'Elle vise cinq cibles rondes avec son arme.'::text),
(298142,33127,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O silahını ... yuvarlak hedefe doğrultuyor.'::text,'beş'::text,'beşinci'::text,'beşinci'::text,'O silahını beş yuvarlak hedefe doğrultuyor.'::text),
(298143,33127,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... kerek célpontra céloz a fegyverével.'::text,'öt'::text,'ötödik'::text,'ötödik'::text,'Ő öt kerek célpontra céloz a fegyverével.'::text),
(298155,33129,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du fährst sonst Ski, aber gerade ... du mit deinem Gewehr. Ikonisch.'::text,'zielst'::text,'zielst'::text,NULL::text,'Du fährst sonst Ski, aber gerade zielst du mit deinem Gewehr. Ikonisch.'::text),
(298159,33129,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти зазвичай катаєшся на лижах, але зараз ти ... з рушниці. Легенда.'::text,'цілишся'::text,'цілишся'::text,NULL::text,'Ти зазвичай катаєшся на лижах, але зараз ти цілишся з рушниці. Легенда.'::text),
