(298157,33129,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude tu skies, mais là tu ... avec ton arme. Iconique.'::text,'es en train de viser'::text,'vises'::text,NULL::text,'D''habitude tu skies, mais là tu es en train de viser avec ton arme. Iconique.'::text),
