(297003,33001,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Trainerregel! Der Feldspieler ... seinen Handschuh tragen. Sonst totale Katastrophe!'::text,'muss'::text,'muss'::text,'sollte'::text,'Trainerregel! Der Feldspieler muss seinen Handschuh tragen. Sonst totale Katastrophe!'::text),
