(297006,33001,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Norma del entrenador! El jugador ... llevar su guante. ¡Si no, desastre total!'::text,'tiene que'::text,'debe'::text,'debería'::text,'¡Norma del entrenador! El jugador tiene que llevar su guante. ¡Si no, desastre total!'::text),
(297005,33001,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Règle du coach ! Le joueur ... porter son gant. Sinon, catastrophe totale !'::text,'doit'::text,'doit'::text,'devrait'::text,'Règle du coach ! Le joueur doit porter son gant. Sinon, catastrophe totale !'::text),
