(317247,35250,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, ... zapatillas de oveja en tus pies son monísimas.'::text,'estas'::text,'esta'::text,'esa'::text,'Sinceramente, estas zapatillas de oveja en tus pies son monísimas.'::text),
