(301066,33452,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... у сумці? Нелегальний сир і ковбаси.'::text,'Що'::text,'Хто'::text,'Де'::text,'Що у сумці? Нелегальний сир і ковбаси.'::text),
