(317793,35311,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich beeindruckend: Du zählst bis zehn, und Schneeflocke Nummer ... landet.'::text,'zehn'::text,'zehnte'::text,'Zehnen'::text,'Ehrlich beeindruckend: Du zählst bis zehn, und Schneeflocke Nummer zehn landet.'::text),
