(306792,34088,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... reggel találja meg a cetlit.'::text,'hétfőn'::text,'hétfőben'::text,'hétfőkor'::text,'Ő hétfőn reggel találja meg a cetlit.'::text),
(306822,34092,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, sie ist mit dem Zettel aufgestanden, also ... sie anscheinend alle fragen.'::text,'wird'::text,'wird'::text,NULL::text,'Bestie, sie ist mit dem Zettel aufgestanden, also wird sie anscheinend alle fragen.'::text),
(306826,34092,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона встала з запискою, тож, кажуть, ...'::text,'збирається спитати всіх'::text,'спитає всіх'::text,NULL::text,'Подруго, вона встала з запискою, тож, кажуть, збирається спитати всіх.'::text),
(306825,34092,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, ella se ha levantado con la nota, así que al parecer ... preguntar a todo el mundo.'::text,'va a'::text,NULL::text,NULL::text,'Amiga, ella se ha levantado con la nota, así que al parecer va a preguntar a todo el mundo.'::text),
(306824,34092,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, elle s''est levée avec le mot, donc apparemment elle ... demander à tout le monde.'::text,'va'::text,NULL::text,NULL::text,'Ma belle, elle s''est levée avec le mot, donc apparemment elle va demander à tout le monde.'::text),
(306827,34092,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kankam, o notla ayağa kalktı, yani anlaşılan herkese ...'::text,'soracak'::text,'soracak'::text,NULL::text,'Kankam, o notla ayağa kalktı, yani anlaşılan herkese soracak.'::text),
(306828,34092,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, ő felállt a cetlivel, szóval állítólag mindenkit meg ... kérdezni.'::text,'fog'::text,'fog'::text,NULL::text,'Csajszi, ő felállt a cetlivel, szóval állítólag mindenkit meg fog kérdezni.'::text),
(318225,35359,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie haben ... Sohn, weil ein Junge ein Sohn ist.'::text,'einen'::text,'ersten'::text,'einmal'::text,'Sie haben einen Sohn, weil ein Junge ein Sohn ist.'::text),
(318229,35359,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони мають ... сина, бо один хлопчик — це один син.'::text,'одного'::text,'першого'::text,'раз'::text,'Вони мають одного сина, бо один хлопчик — це один син.'::text),
(318228,35359,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellos tienen ... hijo, porque un niño es un hijo.'::text,'un'::text,'primer'::text,'una vez'::text,'Ellos tienen un hijo, porque un niño es un hijo.'::text),
(318227,35359,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ont ... fils, parce qu''un garçon, c''est un fils.'::text,'un'::text,'premier'::text,'une fois'::text,'Ils ont un fils, parce qu''un garçon, c''est un fils.'::text),
(318230,35359,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onların ... oğlu var, çünkü bir oğlan bir oğuldur.'::text,'bir'::text,'birinci'::text,'bir kez'::text,'Onların bir oğlu var, çünkü bir oğlan bir oğuldur.'::text),
(318231,35359,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nekik ... fiuk van, mert egy fiú az egy fiú.'::text,'egy'::text,'első'::text,'egyszer'::text,'Nekik egy fiuk van, mert egy fiú az egy fiú.'::text),
(318279,35365,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, Vater und Sohn ... danach Fußball spielen, echt.'::text,'werden'::text,'wird'::text,'werden'::text,'Yo, Vater und Sohn werden danach Fußball spielen, echt.'::text),
(318283,35365,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, тато й син ... потім грати у футбол, реально.'::text,'збираються'::text,'збирається'::text,'збираються'::text,'Йо, тато й син збираються потім грати у футбол, реально.'::text),
(318282,35365,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eh, padre e hijo ... jugar al fútbol después de esto, en serio.'::text,'van a'::text,'va a'::text,'van a'::text,'Eh, padre e hijo van a jugar al fútbol después de esto, en serio.'::text),
(318281,35365,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, le père et le fils ... jouer au foot après ça, grave.'::text,'vont'::text,'va'::text,'vont'::text,'Yo, le père et le fils vont jouer au foot après ça, grave.'::text),
(318284,35365,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, baba oğul bundan sonra futbol ..., cidden.'::text,'oynayacaklar'::text,'oynayacak'::text,'oynayacaklar'::text,'Kanka, baba oğul bundan sonra futbol oynayacaklar, cidden.'::text),
(318285,35365,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, apa és fia ez után focizni ..., komolyan.'::text,'fognak'::text,'fog'::text,'fognak'::text,'Figyu, apa és fia ez után focizni fognak, komolyan.'::text),
(310377,34487,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, sie ... ihre Postkarten wie einen Fächer aus, weil sie stolz ist.'::text,'breitet'::text,'ausbreiten'::text,'ausbreitend'::text,'Yo, sie breitet ihre Postkarten wie einen Fächer aus, weil sie stolz ist.'::text),
(310381,34487,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, вона ... свої листівки віялом, бо пишається.'::text,'розкладає'::text,'розкладати'::text,'розкладаючи'::text,'Йо, вона розкладає свої листівки віялом, бо пишається.'::text),
(310380,34487,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eh, ella ... sus postales en abanico porque está orgullosa.'::text,'despliega'::text,'desplegar'::text,'desplegando'::text,'Eh, ella despliega sus postales en abanico porque está orgullosa.'::text),
(310379,34487,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, elle ... ses cartes postales en éventail parce qu''elle est fière.'::text,'étale'::text,'étaler'::text,'étalant'::text,'Yo, elle étale ses cartes postales en éventail parce qu''elle est fière.'::text),
(310382,34487,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o kartpostallarını yelpaze gibi ... çünkü gururlu.'::text,'açar'::text,'açmak'::text,'açarak'::text,'Kanka, o kartpostallarını yelpaze gibi açar çünkü gururlu.'::text),
(310383,34487,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, ő legyezőszerűen ... a képeslapjait, mert büszke.'::text,'szétteríti'::text,'szétteríteni'::text,'szétterítő'::text,'Figyu, ő legyezőszerűen szétteríti a képeslapjait, mert büszke.'::text),
(310422,34492,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... ihre Postkarten schreiben, bevor sie nach Hause fliegt.'::text,'sollte'::text,'sollte'::text,'sollte'::text,'Sie sollte ihre Postkarten schreiben, bevor sie nach Hause fliegt.'::text),
(310426,34492,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... написати свої листівки, перш ніж полетить додому.'::text,'мала б'::text,'мала б'::text,'мала б'::text,'Вона мала б написати свої листівки, перш ніж полетить додому.'::text),
(310425,34492,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... escribir sus postales antes de volar a casa.'::text,'debería'::text,'debería'::text,'debería'::text,'Ella debería escribir sus postales antes de volar a casa.'::text),
(310424,34492,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... écrire ses cartes postales avant de rentrer en avion.'::text,'devrait'::text,'devrait'::text,'devrait'::text,'Elle devrait écrire ses cartes postales avant de rentrer en avion.'::text),
(310427,34492,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O eve uçmadan önce kartpostallarını ...'::text,'yazmalı'::text,'yazmalı'::text,'yazmalı'::text,'O eve uçmadan önce kartpostallarını yazmalı.'::text),
(310428,34492,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neki ... megírnia a képeslapjait, mielőtt hazarepül.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Neki kellene megírnia a képeslapjait, mielőtt hazarepül.'::text),
(318540,35394,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... zur Menge, und sie schreien!'::text,'spricht'::text,'sprechen'::text,'sprechend'::text,'Sie spricht zur Menge, und sie schreien!'::text),
(318544,35394,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... до натовпу, і вони кричать!'::text,'говорить'::text,'говорити'::text,'говорячи'::text,'Вона говорить до натовпу, і вони кричать!'::text),
(318543,35394,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella ... a la multitud y gritan!'::text,'habla'::text,'hablar'::text,'hablando'::text,'¡Ella habla a la multitud y gritan!'::text),
(318542,35394,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... à la foule, et ils crient !'::text,'parle'::text,'parler'::text,'parlant'::text,'Elle parle à la foule, et ils crient !'::text),
(318545,35394,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kalabalığa ..., onlar da çığlık atıyor!'::text,'konuşur'::text,'konuşmak'::text,'konuşarak'::text,'O kalabalığa konuşur, onlar da çığlık atıyor!'::text),
(318546,35394,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... a tömeghez, és azok sikítanak!'::text,'beszél'::text,'beszélni'::text,'beszélő'::text,'Ő beszél a tömeghez, és azok sikítanak!'::text),
(318567,35397,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern ... sie zu einer großen Menge auf dem Platz.'::text,'sprach'::text,'spricht'::text,'sprach'::text,'Gestern sprach sie zu einer großen Menge auf dem Platz.'::text),
(318571,35397,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора вона ... до великого натовпу на площі.'::text,'говорила'::text,'говорить'::text,'говорила'::text,'Учора вона говорила до великого натовпу на площі.'::text),
(318570,35397,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayer ella ... a una gran multitud en la plaza.'::text,'habló'::text,'habla'::text,'habló'::text,'Ayer ella habló a una gran multitud en la plaza.'::text),
(318569,35397,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier, elle ... à une grande foule sur la place.'::text,'a parlé'::text,'parle'::text,'a parlé'::text,'Hier, elle a parlé à une grande foule sur la place.'::text),
(318572,35397,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün o meydanda büyük bir kalabalığa ...'::text,'konuştu'::text,'konuşur'::text,'konuştu'::text,'Dün o meydanda büyük bir kalabalığa konuştu.'::text),
(318573,35397,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap ő ... egy nagy tömeghez a téren.'::text,'beszélt'::text,'beszél'::text,'beszélt'::text,'Tegnap ő beszélt egy nagy tömeghez a téren.'::text),
(326829,36315,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Spinne hängt unter dem Netz, ... sie auf Futter wartet.'::text,'weil'::text,'aber'::text,'also'::text,'Die Spinne hängt unter dem Netz, weil sie auf Futter wartet.'::text),
(326833,36315,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Павук висить під павутиною, ... чекає на їжу.'::text,'бо'::text,'але'::text,'тому'::text,'Павук висить під павутиною, бо чекає на їжу.'::text),
(326832,36315,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La araña cuelga bajo la telaraña ... espera comida.'::text,'porque'::text,'pero'::text,'así que'::text,'La araña cuelga bajo la telaraña porque espera comida.'::text),
(326831,36315,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''araignée est suspendue sous la toile ... attend de la nourriture.'::text,'parce qu''elle'::text,'mais elle'::text,'donc elle'::text,'L''araignée est suspendue sous la toile parce qu''elle attend de la nourriture.'::text),
(326834,36315,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Örümcek ağın altında asılı duruyor ... yiyecek bekliyor.'::text,'çünkü'::text,'ama'::text,'bu yüzden'::text,'Örümcek ağın altında asılı duruyor çünkü yiyecek bekliyor.'::text),
(326835,36315,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pók a háló alatt lóg, ... élelemre vár.'::text,'mert'::text,'de'::text,'ezért'::text,'A pók a háló alatt lóg, mert élelemre vár.'::text),
(316947,35217,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du läufst sonst schnell Schlittschuh, aber jetzt ... du langsam Schlittschuh. So elegant, ehrlich.'::text,'läufst'::text,'läufst'::text,NULL::text,'Du läufst sonst schnell Schlittschuh, aber jetzt läufst du langsam Schlittschuh. So elegant, ehrlich.'::text),
(316951,35217,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти зазвичай катаєшся швидко, але зараз ти ... повільно. Так плавно, чесно.'::text,'катаєшся'::text,'катаєшся'::text,NULL::text,'Ти зазвичай катаєшся швидко, але зараз ти катаєшся повільно. Так плавно, чесно.'::text),
(316950,35217,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente tú patinas rápido, pero ahora ... despacio. Qué estilo, de verdad.'::text,'estás patinando'::text,'patinas'::text,NULL::text,'Normalmente tú patinas rápido, pero ahora estás patinando despacio. Qué estilo, de verdad.'::text),
(316949,35217,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude tu patines vite, mais là tu ... lentement. Trop fluide, franchement.'::text,'es en train de patiner'::text,'patines'::text,NULL::text,'D''habitude tu patines vite, mais là tu es en train de patiner lentement. Trop fluide, franchement.'::text),
(316952,35217,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen genelde hızlı paten kayarsın ama şimdi yavaş ..., çok akıcı, açıkçası.'::text,'kayıyorsun'::text,'kayarsın'::text,NULL::text,'Sen genelde hızlı paten kayarsın ama şimdi yavaş kayıyorsun, çok akıcı, açıkçası.'::text),
(316953,35217,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te általában gyorsan korcsolyázol, de most lassan ..., olyan elegáns, őszintén.'::text,'korcsolyázol'::text,'korcsolyázol'::text,NULL::text,'Te általában gyorsan korcsolyázol, de most lassan korcsolyázol, olyan elegáns, őszintén.'::text),
(319782,35532,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Er wirft ... Stein in den See! Er ist für immer weg!'::text,'seinen'::text,'ihren'::text,'ihren'::text,'Katastrophe! Er wirft seinen Stein in den See! Er ist für immer weg!'::text),
(319786,35532,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Він кидає ... камінь в озеро! Він зник назавжди!'::text,'свій'::text,'свій'::text,'свій'::text,'Катастрофа! Він кидає свій камінь в озеро! Він зник назавжди!'::text),
(319785,35532,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡Él tira ... piedra al lago! ¡Se ha ido para siempre!'::text,'su'::text,'su'::text,'su'::text,'¡Desastre! ¡Él tira su piedra al lago! ¡Se ha ido para siempre!'::text),
(319784,35532,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! Il jette ... pierre dans le lac ! Elle est partie pour toujours !'::text,'sa'::text,'sa'::text,'leur'::text,'Catastrophe ! Il jette sa pierre dans le lac ! Elle est partie pour toujours !'::text),
(319787,35532,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! O ... taşını göle atıyor! Sonsuza dek gitti!'::text,'onun'::text,'onun'::text,'onların'::text,'Felaket! O onun taşını göle atıyor! Sonsuza dek gitti!'::text),
(319788,35532,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! Ő bedobja a ... a tóba! Örökre eltűnt!'::text,'kövét'::text,'kövét'::text,'kövüket'::text,'Katasztrófa! Ő bedobja a kövét a tóba! Örökre eltűnt!'::text),
(319809,35535,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein winziges Kieselsteinchen, klar: In seinen Händen ... ein riesiger Stein.'::text,'ist'::text,'sind'::text,'sein'::text,'Ein winziges Kieselsteinchen, klar: In seinen Händen ist ein riesiger Stein.'::text),
(319813,35535,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Крихітний камінчик, звісно: у його руках ... один величезний камінь.'::text,'є'::text,'є'::text,'бути'::text,'Крихітний камінчик, звісно: у його руках є один величезний камінь.'::text),
(319812,35535,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un guijarro diminuto, obviamente: ... una piedra enorme en sus manos.'::text,'hay'::text,'hay'::text,'hay'::text,'Un guijarro diminuto, obviamente: hay una piedra enorme en sus manos.'::text),
(319811,35535,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un minuscule caillou, évidemment : ... une énorme pierre dans ses mains.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Un minuscule caillou, évidemment : il y a une énorme pierre dans ses mains.'::text),
(319814,35535,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minicik bir çakıl taşı tabii: ellerinde kocaman bir taş ...'::text,'var'::text,'var'::text,'olmak'::text,'Minicik bir çakıl taşı tabii: ellerinde kocaman bir taş var.'::text),
(319815,35535,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Apró kavics, persze: a kezében egy hatalmas kő ...'::text,'van'::text,'vannak'::text,'lenni'::text,'Apró kavics, persze: a kezében egy hatalmas kő van.'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
where l.id = v.id and l.exercise_id = v.eid and l.language_code = v.lang and l.intro_text is not distinct from v.o_intro_text and l.correct_answer is not distinct from v.o_correct_answer and l.distractor_1 is not distinct from v.o_distractor_1 and l.distractor_2 is not distinct from v.o_distractor_2 and l.full_sentence is not distinct from v.o_full_sentence
returning l.id;
commit;
